import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.Ddyno5UB.js";const k=JSON.parse('{"title":"Building Images","description":"","frontmatter":{},"headers":[],"relativePath":"containers/3-building-images.md","filePath":"containers/3-building-images.md"}'),t={name:"containers/3-building-images.md"};function l(p,s,h,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="building-images" tabindex="-1">Building Images <a class="header-anchor" href="#building-images" aria-label="Permalink to &quot;Building Images&quot;">​</a></h1><p>While using pre-built images from Docker Hub is great, engineering requires building your own custom applications into immutable container images using a <code>Dockerfile</code>.</p><h2 id="the-dockerfile" tabindex="-1">The Dockerfile <a class="header-anchor" href="#the-dockerfile" aria-label="Permalink to &quot;The Dockerfile&quot;">​</a></h2><p>A <code>Dockerfile</code> is a declarative script containing step-by-step instructions on how to build your image.</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Always start from a base image (Use Alpine for tiny image sizes!)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:18-alpine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Set the working directory inside the container</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Copy package.json first to leverage Docker&#39;s layer caching</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package.json package-lock.json ./</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Run commands to install dependencies</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm ci --only=production</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Copy the rest of the application source code</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 6. Declare the port the app listens on</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 7. The final command to execute when the container starts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;server.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>To build this image, you run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-node-app:1.0.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h2 id="layer-caching-why-order-matters" tabindex="-1">Layer Caching (Why Order Matters) <a class="header-anchor" href="#layer-caching-why-order-matters" aria-label="Permalink to &quot;Layer Caching (Why Order Matters)&quot;">​</a></h2><p>Remember that images are built in <strong>layers</strong> (UnionFS). Docker executes each line in the <code>Dockerfile</code> and saves it as a cached layer.</p><p>If you change a line in your <code>Dockerfile</code> (or if a <code>COPY</code> command detects that a file on your host machine changed), <strong>that layer and every single layer after it breaks cache and must be rebuilt.</strong></p><p>This is why we <code>COPY package.json</code> and run <code>npm ci</code> <em>before</em> we <code>COPY . .</code> (the rest of the source code). If you only changed a typo in your <code>index.html</code>, Docker will use the cached <code>npm ci</code> layer and build instantly. If you copied the source code <em>before</em> installing dependencies, Docker would reinstall all npm packages every time you fixed a typo!</p><h2 id="the-dockerignore-file" tabindex="-1">The <code>.dockerignore</code> File <a class="header-anchor" href="#the-dockerignore-file" aria-label="Permalink to &quot;The \`.dockerignore\` File&quot;">​</a></h2><p>Just like <code>.gitignore</code>, you should never build an image without a <code>.dockerignore</code> file. If you don&#39;t ignore your local <code>node_modules</code> or <code>.git</code> folders, the <code>COPY . .</code> command will copy hundreds of megabytes of garbage into your container image.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Example .dockerignore</span></span>
<span class="line"><span>node_modules/</span></span>
<span class="line"><span>.git/</span></span>
<span class="line"><span>npm-debug.log</span></span>
<span class="line"><span>Dockerfile</span></span>
<span class="line"><span>.env</span></span></code></pre></div><h2 id="multi-stage-builds" tabindex="-1">Multi-Stage Builds <a class="header-anchor" href="#multi-stage-builds" aria-label="Permalink to &quot;Multi-Stage Builds&quot;">​</a></h2><p>When building compiled languages like Go, Rust, or C++, you need heavy build tools (compilers, headers) to create the binary. However, your final production container <em>only</em> needs the binary itself, not the compiler.</p><p><strong>Multi-stage builds</strong> solve this by allowing you to use multiple <code>FROM</code> statements. You build the app in a massive &quot;builder&quot; image, and then copy just the finished binary into a tiny, secure &quot;runtime&quot; image.</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stage 1: The Builder (Huge image with Go compiler)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> golang:1.21 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> builder</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Compile a statically linked binary</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CGO_ENABLED=0 GOOS=linux go build -o myapp .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stage 2: The Runtime (Scratch is a 0-byte totally empty image!)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scratch</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy ONLY the binary from the builder stage</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=builder /app/myapp /myapp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Execute it</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/myapp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The resulting image might be exactly 5MB, rather than 800MB!</p>`,19)])])}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
